  scout: { version: 1, role: 'scout', description: 'Reads visible trail signs and marks discovered routes.', passiveInformation: ['visible trail signs', 'explored route branches'], informationBoundary: 'in-world-discovery', legalActions: ['observe', 'mark'], cooldownOwner: 'companion', resourceOwner: 'companion', directActions: ['observe', 'mark'], autonomousPriorities: ['inspect visible signs', 'mark already discovered hazards'], prohibitedActions: ['reveal hidden-room locations', 'intercept attacks', 'alter terrain'] },
  pathmaker: { version: 1, role: 'pathmaker', description: 'Supports terrain crossings and stable traversal.', passiveInformation: ['visible terrain blockers', 'explored traversal links'], informationBoundary: 'explored-only', legalActions: ['traverse', 'stabilizeTerrain'], cooldownOwner: 'companion', resourceOwner: 'companion', directActions: ['traverse', 'stabilizeTerrain'], autonomousPriorities: ['stabilize the active route', 'support the courier at a visible crossing'], prohibitedActions: ['reveal hidden-room locations', 'ward hazards', 'intercept attacks'] },
