export const COMPANION_ROLE_CONTRACTS = contracts
export const companionRoleContract = (role: CompanionRole): CompanionRoleContract => ({ ...contracts[role], passiveInformation: [...contracts[role].passiveInformation], legalActions: [...contracts[role].legalActions], directActions: [...contracts[role].directActions], autonomousPriorities: [...contracts[role].autonomousPriorities], prohibitedActions: [...contracts[role].prohibitedActions] })
export const companionRoleContractErrors = (contract: CompanionRoleContract): string[] => {
  const errors: string[] = []
  if (contract.version !== 1) errors.push('unsupported version')
  if (!contract.description || !contract.passiveInformation.length || !contract.legalActions.length || !contract.directActions.length || !contract.autonomousPriorities.length || !contract.prohibitedActions.length) errors.push('incomplete role contract')
  if (contract.cooldownOwner !== 'companion' || contract.resourceOwner !== 'companion') errors.push('invalid ownership')
  if (contract.directActions.some(action => !contract.legalActions.includes(action))) errors.push('direct action is not legal')
  if (contract.role === 'ritualist' && (contract.contentConstraint !== 'TR-01' || !contract.fictionNote?.includes('Jomon-inspired fiction'))) errors.push('missing TR-01 fiction constraint')
  if (contract.role !== 'ritualist' && (contract.contentConstraint || contract.fictionNote)) errors.push('unexpected ritual constraint')
  if (contract.passiveInformation.some(info => info.includes('hidden-room location')) || contract.prohibitedActions.every(action => action !== 'reveal hidden-room locations')) errors.push('hidden-information boundary missing')
  return errors
}
export const isLegalCompanionRoleAction = (role: CompanionRole, action: CompanionActionCategory): boolean => contracts[role].legalActions.includes(action)
